import type { Bot } from "grammy";
import type { Message, MessageEntity } from "grammy/types";

import type { ReplyTarget } from "./types.js";

/** The URL is assembled from Telegram identifiers, never generated by the model. */
function messageLink(chatId: number, target: ReplyTarget): string | null {
  if (!target.messageId) return null;
  const username = target.chatUsername?.replace(/^@/, "");
  if (username && /^[a-zA-Z0-9_]{1,32}$/.test(username)) {
    return `https://t.me/${username}/${target.messageId}`;
  }
  const channelId = -chatId - 1_000_000_000_000;
  return Number.isSafeInteger(channelId) && channelId > 0
    ? `https://t.me/c/${channelId}/${target.messageId}`
    : null;
}

/** Replies stay under their root even when Telegram hides the opposing bot's message. */
export async function sendConversationReply(
  bot: Bot,
  chatId: number,
  text: string,
  target: ReplyTarget,
): Promise<Message> {
  const root = target.rootMessageId ?? target.messageId;
  if (root !== undefined && (!Number.isSafeInteger(root) || root <= 0)) {
    throw new Error("Reply root is not a usable Telegram message");
  }
  if (
    target.messageId !== undefined &&
    (!Number.isSafeInteger(target.messageId) || target.messageId <= 0)
  ) {
    throw new Error("Reply recipient is not a usable Telegram message");
  }
  const name = target.authorName?.replace(/[\r\n]/g, " ").trim() || "собеседнику";
  const prefix = target.messageId ? `↪ Ответ ${name}\n\n` : "";
  const budget = 4096 - prefix.length;
  if (budget <= 0) throw new Error("Reply recipient label exceeds Telegram's text limit");
  let body = text.slice(0, budget);
  // Entity lengths and Telegram's text limit use UTF-16; keep surrogate pairs whole.
  if (/[\uD800-\uDBFF]$/u.test(body)) body = body.slice(0, -1);
  const url = messageLink(chatId, target);
  const entities: MessageEntity[] = url
    ? [{ type: "text_link", offset: 0, length: prefix.length - 2, url }]
    : [];
  return bot.api.sendMessage(chatId, prefix + body, {
    entities,
    ...(root !== undefined && {
      reply_parameters: { message_id: root, allow_sending_without_reply: false },
    }),
    ...(target.messageThreadId !== undefined && { message_thread_id: target.messageThreadId }),
  });
}
